CREATE OR REPLACE FUNCTION public.rpc_sales(p_world uuid, p_def text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare me uuid := auth.uid();
